+)
+foreach ($id in @('FR-MCP-BUILD-001', 'FR-MCP-USECASE-001', 'FR-MCP-USECASE-016', 'FR-MCP-USECASE-017', 'FR-MCP-PATHNORM-001', 'TR-MCP-NUKE-019', 'TR-MCP-NUKE-018', 'TR-MCP-USECASE-018', 'TR-MCP-USECASE-019', 'TR-MCP-QUALITY-001', 'TR-MCP-PATHNORM-001', 'TEST-MCP-USECASE-019', 'TEST-MCP-USECASE-020', 'TEST-MCP-PATHNORM-001')) {
