+[CmdletBinding()]
+param([ValidateSet('Git', 'GitHub', 'Transcript', 'Runs', 'Progress', 'Files')][string]$Mode, [string]$Pattern = '*')
+$ErrorActionPreference = 'Stop'
+$evidence = [ordered]@{ TimestampLocal = Get-Date -Format s; Mode = $Mode }
+switch ($Mode) {
+    'Git' {
+        $evidence.Head = (& git rev-parse HEAD | Out-String).Trim()
+        $evidence.CodeHead = (& git rev-parse b4ad42aa | Out-String).Trim()
+        $evidence.Base = (& git merge-base 3da2db93 a94579db | Out-String).Trim()
+        $evidence.Commits = @(& git log --first-parent '--format=%h %aI %s' '3da2db93..a94579db')
+        $evidence.ChangedCode = @(& git diff --name-only '3da2db93...a94579db' -- . ':!docs')
+        $afterCode = @(& git diff --name-only 'b4ad42aa..a94579db')
+        $evidence.AfterCodePathCount = $afterCode.Count
+        $evidence.AfterCodeOutsideDocs = @($afterCode | Where-Object { -not $_.StartsWith('docs/') })
+        $evidence.RoundTwoPaths = @(& git diff --name-only '6b4295b7..b4ad42aa')
