+        if ($LASTEXITCODE -eq 0) { $evidence.Pr = ($prJson -join "`n") | ConvertFrom-Json }
+        $activityJson = & gh api 'repos/sharpninja/McpServer/activity?ref=fix%2Funit-suite-green-20261019&per_page=100'
+        $evidence.ActivityExitCode = $LASTEXITCODE
+        if ($LASTEXITCODE -eq 0) { $evidence.Activity = ($activityJson -join "`n") | ConvertFrom-Json }
+    }
+    'Transcript' {
+        $path = '/home/sharpninja/.claude/projects/-home-sharpninja-github-McpServer/cea7a82d-3843-4f79-8b4a-4f40d4a21532.jsonl'
+        $users = [System.Collections.Generic.List[object]]::new()
+        $commands = [System.Collections.Generic.List[object]]::new()
+        $edits = [System.Collections.Generic.List[object]]::new()
+        $lineNumber = 0
+        foreach ($line in [System.IO.File]::ReadLines($path)) {
+            $lineNumber++
+            if (-not $line.Contains('"timestamp"')) { continue }
+            $item = $line | ConvertFrom-Json
+            if (-not $item.timestamp) { continue }
+            $stamp = [DateTimeOffset]::Parse($item.timestamp)
+            if ($stamp -lt [DateTimeOffset]::Parse('2026-10-19T14:00:00-05:00') -or $stamp -gt [DateTimeOffset]::Parse('2026-10-19T21:28:28-05:00')) { continue }
+            $local = $stamp.ToLocalTime().ToString('s')
+            if ($item.type -eq 'user') {
+                $userText = if ($item.message.content -is [string]) { $item.message.content } else { (@($item.message.content | Where-Object type -EQ 'text' | ForEach-Object text) -join "`n") }
+                if ($userText) { $users.Add([pscustomobject]@{ Line = $lineNumber; TimestampLocal = $local; Text = $userText }) }
+            }
+            if ($item.type -eq 'assistant') {
+                foreach ($block in $item.message.content) {
+                    if ($block.type -eq 'tool_use') {
+                        if ($block.name -match 'Bash|execute_command') {
+                            $commands.Add([pscustomobject]@{ Line = $lineNumber; TimestampLocal = $local; Tool = $block.name; Command = $block.input.command })
+                        } elseif ($block.name -match 'Write|Edit|apply_patch') {
+                            $edits.Add([pscustomobject]@{ Line = $lineNumber; TimestampLocal = $local; Tool = $block.name; Input = $block.input })
+                        }
+                    }
+                }
+            }
+        }
+        $evidence.UserMessages = @($users)
+        $evidence.Commands = @($commands)
+        $evidence.Edits = @($edits)
+        $evidence.TranscriptPath = $path
+        $evidence.LinesRead = $lineNumber
+    }
+    'Runs' {
+        $records = [System.Collections.Generic.List[object]]::new()
+        $runsRoot = '/home/sharpninja/.claude/scratch/pr82-review-20261019/runs'
