+            $meta = Get-Content -LiteralPath $metaFile.FullName -Raw | ConvertFrom-Json
+            $trxFiles = @(Get-ChildItem -LiteralPath (Join-Path './TestResults' $meta.name) -Recurse -Filter '*.trx' -File -ErrorAction SilentlyContinue)
+            if ($meta.name -like '*buildtests*') { $trxFiles = @(Get-ChildItem -LiteralPath $runsRoot -Recurse -Filter '*.trx' -File | Where-Object { $_.FullName.Contains($meta.name) }) }
+            $trxRecords = foreach ($trxFile in $trxFiles) {
+                [xml]$trx = Get-Content -LiteralPath $trxFile.FullName -Raw
+                $results = @($trx.TestRun.Results.UnitTestResult)
+                [pscustomobject]@{ Path = $trxFile.FullName; Counters = $trx.TestRun.ResultSummary.Counters.OuterXml; OutcomeGroups = @($results | Group-Object outcome | ForEach-Object { [pscustomobject]@{ Outcome = $_.Name; Count = $_.Count } }); FailedNames = @($results | Where-Object outcome -NE 'Passed' | ForEach-Object testName); Sha256 = (Get-FileHash -LiteralPath $trxFile.FullName).Hash }
+            }
+            $originalMeta = Join-Path $runsRoot $metaFile.Name
+            $copiesMatch = if (Test-Path -LiteralPath $originalMeta) { (Get-FileHash -LiteralPath $originalMeta).Hash -eq (Get-FileHash -LiteralPath $metaFile.FullName).Hash } else { $null }
+            $records.Add([pscustomobject]@{ Name = $meta.name; Head = $meta.head; Target = $meta.target; Args = $meta.extraArgs; DirtyTracked = @($meta.dirtyPaths | Where-Object { -not $_.StartsWith('??') }); StartedLocal = $meta.startedLocal; ExitText = if ($meta.exitFile -and (Test-Path -LiteralPath $meta.exitFile)) { (Get-Content -LiteralPath $meta.exitFile -Raw).Trim() } else { $null }; MetaCopyMatches = $copiesMatch; Trx = @($trxRecords); Stdout = $meta.stdout; Stderr = $meta.stderr })
+        }
+        $evidence.Runs = @($records)
+    }
+    'Progress' {
+        foreach ($file in Get-ChildItem -LiteralPath $PSScriptRoot -Filter 'hv-ug-r2-test-*.out.log' -File) {
+            Write-Output ('Log=' + $file.Name)
+            Get-Content -LiteralPath $file.FullName -Tail 12
+        }
+        Get-Date -Format s
+        return
+    }
+    'Files' {
+        $evidence.Files = @(Get-ChildItem -LiteralPath '/home/sharpninja/.claude/scratch/pr82-review-20261019' -File -Filter $Pattern | ForEach-Object { [pscustomobject]@{ Path = $_.FullName; Size = $_.Length } })
+    }
+}
